SELECT COUNT(1)
FROM trim_record r
LEFT JOIN tree t ON r.tree_id = t.id

    AND r.worker_id = #{workerId}
    AND r.client_id = #{clientId}
    AND r.tree_id = #{treeId}
    AND r.actual_trim_time >= CAST(#{startDate} AS DATE)
    AND r.actual_trim_time < DATEADD(DAY, 1, CAST(#{endDate} AS DATE))



    AND r.worker_id = #{workerId}
    AND r.client_id = #{clientId}
    AND r.tree_id = #{treeId}
    AND r.actual_trim_time >= CAST(#{startDate} AS DATE)
    AND r.actual_trim_time < DATEADD(DAY, 1, CAST(#{endDate} AS DATE))

ORDER BY r.actual_trim_time DESC, r.id DESC
OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY


WHERE r.task_id = #{taskId}
ORDER BY r.id DESC
OFFSET 0 ROWS FETCH NEXT 1 ROWS ONLY
